    .intro { display: flex; gap: 24px; align-items: flex-start; }
    .chapter { font-size: clamp(60px, 9vw, 100px); line-height: 1; letter-spacing: -.07em; color: var(--blue); font-weight: 300; }
    .intro h1 { font-size: clamp(28px, 3.8vw, 44px); margin-top: 4px; }
    .pill { display: inline-block; font-size: 12px; border: 1px solid var(--line); border-radius: 4px; padding: 3px 9px; margin-bottom: 12px; color: var(--muted); }
    .boundary { position: relative; margin: 36px 0 32px; background: var(--indigo); color: white; padding: 28px; border-radius: 4px 28px 4px 4px; }
    .boundary h2 { color: white; margin: 0 0 24px; font-size: 18px; }
