    table { border-collapse: collapse; font-size: 13px; min-width: 100%; }
    td, th { text-align: left; vertical-align: top; padding: 10px 12px; border-bottom: 1px solid var(--line); }
    th { font-weight: 600; }
    .source { font-size: 12px; color: var(--muted); margin: 20px 0; overflow-wrap: anywhere; }
    .pager { display: flex; justify-content: space-between; gap: 20px; margin-top: 32px; font-size: 14px; }
    .action-row { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; margin: 18px 0; }
