    .exercise summary { font-weight: 600; font-size: 15px; }
    .exercise details .document { margin-top: 16px; }
    .toolbar-actions, .languages { display: flex; align-items: center; gap: 8px; }
    .languages button { padding: 5px 9px; border: 1px solid var(--line); border-radius: 5px; color: var(--ink); background: var(--surface); font-size: 12px; }
    .languages button[aria-pressed="true"] { background: var(--wash); color: var(--blue); border-color: var(--blue); font-weight: 650; }
    .symbol { width: 19px; height: 19px; flex-shrink: 0; vertical-align: middle; }
