    .workspace-option strong, .workspace-option span { display: block; }
    .workspace-option span { margin-top: 8px; color: var(--muted); font-size: 13px; }
    .brands { display: flex; flex-wrap: wrap; align-items: center; gap: 18px; margin: 24px 0; font-size: 13px; }
    .product { display: inline-flex; align-items: center; gap: 8px; }
    .product img { width: 30px; height: 30px; object-fit: contain; padding: 2px; background: white; }
    details { margin-top: 24px; color: var(--muted); font-size: 13px; }
    summary { cursor: pointer; color: var(--ink); font-size: 15px; font-weight: 600; }
    details[open] > summary { margin-bottom: 16px; }
    details .document, .document details { font-size: 15px; }
    details p { white-space: pre-wrap; overflow-wrap: anywhere; }
    @media (prefers-color-scheme: dark) {
      :root { color-scheme: dark; --paper: #172339; --surface: #1e2d45; --ink: #eef3ff; --muted: #b1c1db; --line: #405474; --blue: #8fbaff; --wash: #273f64; --success: #7cddb0; --error: #ff9fa8; }
      .primary { background: #245ed2; color: #fff; }
    }
    @media (max-width: 850px) { .shell { grid-template-columns: 210px minmax(0, 1fr); } .rail { padding: 24px 12px; } main { padding: 32px 24px; } .toolbar { padding: 16px 24px; } #message { padding-left: 24px; padding-right: 24px; } .chain { grid-template-columns: 1fr; } .connector { width: 1px; height: 16px; margin-left: 20px; } .connector::after { right: -3px; top: 10px; transform: rotate(135deg); } .node { min-height: auto; } }
    @media (max-width: 570px) { .shell { display: block; } .rail { position: static; height: auto; padding: 20px; border-right: 0; border-bottom: 1px solid var(--line); } .brand small, .rail-footer, .nav-label { display: none; } #module-nav { display: flex; overflow-x: auto; margin: 16px -4px 0; padding: 4px; } #module-nav a { flex-shrink: 0; padding: 10px; margin: 0 4px 0 0; } #module-nav .nav-title { display: none; } #resource-nav { display: flex; flex-wrap: wrap; margin-top: 12px; } #resource-nav a { font-size: 12px; padding: 6px 10px; } main { padding: 28px 20px; } .toolbar { padding: 12px 20px; } .toolbar span { max-width: 200px; } .intro { gap: 16px; } .document { padding: 8px 18px 22px; } .route-item { grid-template-columns: 32px 1fr; gap: 12px; } .availability { grid-column: 2; } }
    @media (max-width: 570px) { .launch-panel { padding: 18px; } .command-head { flex-direction: column; align-items: flex-start; gap: 8px; } }
    @media (max-width: 570px) { .toolbar { flex-wrap: wrap; } .toolbar-actions { flex-wrap: wrap; } .next-step { padding: 18px; } }
  </style>
</head>
<body>
  <a href="#content" class="skip">Skip to content</a>
  <div class="shell">
    <aside class="rail">
      <a class="brand" href="#/overview"><span class="brand-mark" aria-hidden="true">GM</span><span>Governed MCP<small>A hands-on Azure workshop</small></span></a>
      <p class="nav-label">Start</p>
      <nav id="start-nav" aria-label="Start here"></nav>
      <p class="nav-label">Main route</p>
      <nav id="module-nav" aria-label="Workshop modules"></nav>
      <p class="nav-label">References</p>
      <nav id="resource-nav" aria-label="Workshop references">
        <a href="#/overview">Workshop overview</a>
        <a href="#/practice">Try your MCP</a>
        <a href="#/runbook">Build runbook</a>
        <a href="#/sources">Verified sources</a>
        <a href="#/decisions">Build decisions</a>
      </nav>
      <p class="rail-footer">Copilot canvas SDK: Preview.<br>Read the steps. Run locally. Validate before continuing.</p>
    </aside>
    <div class="stage">
      <header class="toolbar"><span>Workshop build board / self-paced guide</span><div class="toolbar-actions"><div class="languages" role="group" aria-label="Language / Langue"><button id="language-en" type="button" lang="en" aria-label="English">EN</button><button id="language-fr" type="button" lang="fr" aria-label="Français">FR</button></div><button class="refresh" id="refresh" type="button">Refresh content</button></div></header>
      <p id="message" role="status" aria-live="polite"></p>
      <main id="content" tabindex="-1" aria-label="Workshop content"><h1>Loading the workshop.</h1></main>
    </div>
  </div>
  <script src="locale-fr.js"></script>
  <script>
    const key = "__BOARD_KEY__";
    const staticSite = "__STATIC_SITE__" === "true";
    let state;
    let rawState;
    let language = new URL(location.href).searchParams.get("lang") === "fr" ? "fr" : "en";
    let loading = false;
    const content = document.getElementById("content");
    const message = document.getElementById("message");
    const labels = { todo: "Not built", "in-progress": "Being built", validated: "Validated", blocked: "Build blocked" };
    function t(text) { return language === "fr" && Object.hasOwn(french, text) ? french[text] : text; }
    function element(tag, text, className) {
      const node = document.createElement(tag);
      if (text !== undefined) node.textContent = tag === "code" ? text : t(text);
      if (className) node.className = className;
      return node;
    }
    function symbol(name) {
      const paths = {
        route: "M3 5h12l-3-3m3 3-3 3M17 15H5l3-3m-3 3 3 3",
        book: "M2 3h6l2 2 2-2h6v14h-6l-2 2-2-2H2zM10 5v14",
        shield: "M10 1 18 4v6c0 4-4 7-8 9-4-2-8-5-8-9V4zM6 10l3 3 5-6",
        terminal: "M2 3h16v14H2zM5 7l3 3-3 3m5 0h4",
        tip: "M6 13c-5-5-2-11 4-11s9 6 4 11l-1 3H7zM7 19h6",
        warning: "M10 2 19 18H1zM10 7v5m0 3v1",
        important: "M10 2a8 8 0 1 0 0 16 8 8 0 1 0 0-16M10 6v5m0 3v1",
      };
      const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
      svg.setAttribute("viewBox", "0 0 20 20");
      svg.setAttribute("class", "symbol");
      svg.setAttribute("aria-hidden", "true");
      const path = document.createElementNS(svg.namespaceURI, "path");
      path.setAttribute("d", paths[name] || paths.book);
      path.setAttribute("fill", "none");
      path.setAttribute("stroke", "currentColor");
      path.setAttribute("stroke-width", "1.5");
      path.setAttribute("stroke-linejoin", "round");
      svg.append(path);
      return svg;
    }
    function link(text, href, className) {
      const node = element("a", text, className);
      node.href = href;
      return node;
    }
    function inline(node, text, path) {
      const tokens = /(\[[^\]]+\]\([^\s)]+\)|`[^`]+`|\*\*[^*]+\*\*|https?:\/\/[^\s<>)]+)/g;
      let end = 0;
      for (const match of text.matchAll(tokens)) {
        node.append(document.createTextNode(text.slice(end, match.index)));
        const token = match[0];
        if (token.startsWith("`")) node.append(element("code", token.slice(1, -1)));
        else if (token.startsWith("**")) node.append(element("strong", token.slice(2, -2)));
        else {
          const parts = /^\[([^\]]+)\]\(([^)]+)\)$/.exec(token);
          const target = parts ? parts[2] : token.replace(/[.,;:]+$/, "");
          const label = parts ? parts[1] : target;
          const url = new URL(target, `https://github.com/olivMertens/workshop-mcp/blob/main/${path}`);
          if (["https:", "http:"].includes(url.protocol)) {
            const repositoryUrl = url.origin === "https://github.com" &&
              url.pathname.startsWith("/olivMertens/workshop-mcp/blob/main/");
            const repositoryPath = repositoryUrl ?
              decodeURIComponent(url.pathname).replace(/^\/olivMertens\/workshop-mcp\/blob\/main\//, "") : null;
            const local = Object.entries(state.documents).find(([, doc]) => doc.sourcePath === repositoryPath);
            const localModule = state.modules.find((module) => module.guide !== null && module.sourcePath === repositoryPath);
            const asset = repositoryPath && (
              /^assets\/architecture\/(?:00|01|02|03|04|05|06|07|99)\.(?:en|fr)\.(?:svg|png)$/.test(repositoryPath) ||
              repositoryPath === "assets/architecture/workshop.drawio" ||
              /^assets\/icons\/(?:azure|microsoft|entra|apim|functions|storage|insights|api-center|subscription)\.svg$/.test(repositoryPath));
            const anchor = link(label, local ? `#/${local[0]}` : localModule ? `#/module/${localModule.module}` :
              asset ? `${staticSite ? "" : "/"}${repositoryPath}` : url.href);
            if (!local && !localModule) {
              anchor.target = "_blank";
              anchor.rel = "noopener noreferrer";
            }
            node.append(anchor);
          } else node.append(document.createTextNode(label));
          if (!parts) node.append(document.createTextNode(token.slice(target.length)));
        }
        end = match.index + token.length;
      }
      node.append(document.createTextNode(text.slice(end)));
    }
    function markdown(text, path) {
      const body = element("div", undefined, "document");
      const lines = text.split(/\r?\n/);
      for (let i = 0; i < lines.length;) {
        const line = lines[i];
        if (!line.trim()) { i++; continue; }
        if (line === "<details>") {
          const summary = /^<summary>([^<]+)<\/summary>$/.exec(lines[i + 1] || "");
          if (!summary) throw new Error("A document disclosure needs a plain-text summary.");
          let depth = 1, fenced = false, end = i + 2;
          for (; end < lines.length; end++) {
            if (/^\s*```/.test(lines[end])) fenced = !fenced;
            if (fenced) continue;
            if (lines[end] === "<details>") depth++;
            if (lines[end] === "</details>" && --depth === 0) break;
          }
          if (depth !== 0) throw new Error("A document disclosure is missing its closing tag.");
          const section = element("details");
          const title = element("summary");
          inline(title, summary[1], path);
          section.append(title, markdown(lines.slice(i + 2, end).join("\n"), path));
          body.append(section);
          i = end + 1;
          continue;
        }
        const callout = /^> \[!(TIP|NOTE|IMPORTANT|WARNING|CAUTION)\]\s*$/.exec(line);
        if (callout) {
          const text = [];
          i++;
          while (i < lines.length && /^>/.test(lines[i])) text.push(lines[i++].replace(/^> ?/, ""));
          const types = { TIP: "Tip", NOTE: "Note", IMPORTANT: "Important", WARNING: "Warning", CAUTION: "Danger" };
          const box = notice(types[callout[1]], "", callout[1].toLowerCase());
          const paragraph = element("p");
          inline(paragraph, text.join(" "), path);
          box.append(paragraph);
          body.append(box);
          continue;
        }
        if (/^\s*```/.test(line)) {
          const code = [];
          i++;
          while (i < lines.length && !/^\s*```/.test(lines[i])) code.push(lines[i++]);
          i++;
          if (line.trim() === "```mermaid") {
            const module = state.modules.find((item) => item.diagramSource.content === code.join("\n"));
            if (!module) throw new Error("Mermaid source does not match a published workshop diagram.");
            body.append(architecture(module));
            continue;
          }
          const pre = element("pre");
          pre.append(element("code", code.join("\n")));
          body.append(pre);
          continue;
        }
        if (line.startsWith("|") && /^\|[\s:|-]+\|$/.test(lines[i + 1] || "")) {
          const wrapper = element("div", undefined, "table-scroll");
          const table = element("table");
          let header = true;
          while (i < lines.length && lines[i].startsWith("|")) {
            if (/^\|[\s:|-]+\|$/.test(lines[i])) { i++; continue; }
            const row = element("tr");
            for (const cell of lines[i].split("|").slice(1, -1)) {
              const td = element(header ? "th" : "td");
              if (header) td.scope = "col";
              inline(td, cell.trim(), path);
              row.append(td);
            }
            table.append(row);
            header = false;
            i++;
          }
          wrapper.append(table);
          body.append(wrapper);
          continue;
        }
        const heading = /^(#{1,6}) (.+)$/.exec(line);
        if (heading) {
          const node = element(`h${Math.min(heading[1].length + 1, 6)}`);
          inline(node, heading[2], path);
          body.append(node);
          i++;
          continue;
        }
        const list = /^\s*(?:- |\d+\. )/.test(line);
        const ordered = /^\s*\d+\. /.test(line);
        const node = element(list ? ordered ? "ol" : "ul" : "p");
        if (list) {
          if (ordered) node.start = Number(line.match(/\d+/)[0]);
          while (i < lines.length && (ordered ? /^\s*\d+\. / : /^\s*- /).test(lines[i])) {
            let text = lines[i++].replace(/^\s*(?:- |\d+\. )/, "");
            while (i < lines.length && /^\s+\S/.test(lines[i]) && !/^\s*(?:- |\d+\. |```)/.test(lines[i])) text += " " + lines[i++].trim();
            const item = element("li");
            inline(item, text, path);
            node.append(item);
          }
        } else {
          let text = lines[i++].replace(/^> ?/, "");
          while (i < lines.length && lines[i].trim() && !/^(#|```|\||- |\d+\. |<details>|<\/details>)/.test(lines[i])) text += " " + lines[i++].trim().replace(/^> ?/, "");
          inline(node, text, path);
        }
        body.append(node);
      }
      return body;
    }
    function disclosure(title, ...children) {
      const section = element("details");
      section.append(element("summary", title), ...children);
      return section;
    }
    function notice(title, description, type = "important") {
      const node = element("div", undefined, `notice ${type}`);
      const heading = element("strong");
      heading.append(symbol(type === "tip" ? "tip" : ["warning", "caution"].includes(type) ? "warning" : "important"),
        document.createTextNode(t(title)));
      node.append(heading, document.createTextNode(t(description)));
      return node;
    }
    function moduleLink(module, className) {
      return link(module.title, `#/module/${module.module}`, className);
    }
    function externalLink(text, href, className) {
      const anchor = link(text, href, className);
      anchor.target = "_blank";
      anchor.rel = "noopener noreferrer";
      return anchor;
    }
    function commandBlock(title, text, copyLabel = "Copy command") {
      text = t(text);
      const section = element("section", undefined, "command");
      const heading = element("div", undefined, "command-head");
      const copy = element("button", copyLabel, "copy");
      copy.type = "button";
      copy.setAttribute("aria-label", `${t(copyLabel)}${language === "fr" ? " : " : ": "}${t(title)}`);
      copy.addEventListener("click", async () => {
        try {
          if (!navigator.clipboard?.writeText) throw new Error("Clipboard access is unavailable.");
          await navigator.clipboard.writeText(text);
          message.className = "";
          message.textContent = t("Copied. Nothing has been executed or sent to your MCP server.");
        } catch {
          message.className = "error";
          message.textContent = t("Clipboard access was denied or is unavailable. Select the text below and copy it manually.");
        }
      });
      heading.append(element("span", title), copy);
      const pre = element("pre");
      pre.append(element("code", text));
      section.append(heading, pre);
      return section;
    }
    function connectionCommands(value) {
      if (/\s/.test(value)) throw new Error("Use a single HTTPS URL without spaces or credentials.");
      let url;
      try { url = new URL(value); }
      catch (error) {
        if (!(error instanceof TypeError)) throw error;
        throw new Error("Enter the complete HTTPS endpoint from your deployment outputs.");
      }
      if (url.protocol !== "https:" || url.username || url.password || url.search || url.hash ||
          value.includes("?") || value.includes("#")) {
        throw new Error("Use HTTPS without credentials, query strings or fragments. Never paste a key or token here.");
      }
      const psUrl = url.href.replaceAll("'", "''");
      const bashUrl = url.href.replaceAll("'", "'\\''");
      return {
        powershell: "if ((npm view @modelcontextprotocol/inspector@2.9.0 version) -ne '2.9.0') { throw 'Pinned Inspector unavailable in your configured npm registry.' }\n" +
          "$env:MCP_INSPECTOR_SECRET_STORE = 'memory'\n$env:MCP_INSPECTOR_PERSIST_TOKENS = 'none'\n$env:HOST = '127.0.0.1'\n" +
          `npx @modelcontextprotocol/inspector@2.9.0 --server-url '${psUrl}' --transport http --protocol-era auto`,
        bash: "npm view @modelcontextprotocol/inspector@2.9.0 version && \\\n" +
          "MCP_INSPECTOR_SECRET_STORE=memory MCP_INSPECTOR_PERSIST_TOKENS=none HOST=127.0.0.1 \\\n" +
          `  npx @modelcontextprotocol/inspector@2.9.0 --server-url '${bashUrl}' --transport http --protocol-era auto`,
        configuration: JSON.stringify({ servers: { workshop: { type: "http", url: url.href } } }, null, 2),
      };
    }
    function validationCommands(module) {
      const section = element("div");
      const paths = module.validation;
      if (!paths.powershell && !paths.bash) {
        section.append(element("p", "Module validation is not published yet. No runnable validator is offered.", "field-message"));
        return section;
      }
      section.append(element("p", "From the repository root, after reviewing the module guide and approvals. This can make real calls and create synthetic test data.", "field-message"));
      if (paths.powershell) section.append(commandBlock(`${language === "fr" ? "Vérifier le module" : "Validate module"} ${module.module} / PowerShell`,
        `pwsh -NoProfile -File .\\${paths.powershell.replaceAll("/", "\\")}`));
      if (paths.bash) section.append(disclosure("Using bash",
        commandBlock(`${language === "fr" ? "Vérifier le module" : "Validate module"} ${module.module} / bash`, `bash ./${paths.bash}`)));
      return section;
    }
      function workspaceChoices() {
        const section = element("section", undefined, "workspace-choice");
        section.append(element("h2", "Choose your workspace first"),
          element("p", "Dev container or local terminal: the same scripts, private participant file and Terraform root. No progression form or cloud action."));
        const options = element("div", undefined, "workspace-options");
        for (const [mode, title, description] of [
          ["devcontainer", "VS Code dev container", "Use the checked-in container configuration. Requires an approved, reachable Linux container engine."],
          ["local", "Local terminal", "Use your existing tools without a container. Check them in the terminal you will actually use."],
          ["codespaces", "Codespaces (optional)", "Use the same container in GitHub after publication. Review branch, quota, costs and private forwarding."],
        ]) {
          const anchor = link("", `#/start/${mode}`, "workspace-option");
          anchor.append(element("strong", title), element("span", description));
          options.append(anchor);
        }
        section.append(options);
        return section;
      }
      function showStart(mode) {
        content.append(element("h1", "Your workspace. Your resources."), workspaceChoices());
        if (mode === "devcontainer") {
          content.append(element("h2", "VS Code dev container"),
            commandBlock("Open your existing local checkout in VS Code", "code ."),
            element("p", "In VS Code, run Dev Containers: Reopen in Container. Read the startup log and resolve every failed check. Do not mount host Azure credentials or expose Inspector ports publicly."),
            notice("Container runtime still needs verification.", "The configuration and registry pins were checked, but no reachable engine was available here. Your build and module 00 checks are required.", "warning"));
        } else if (mode === "local") {
          content.append(element("h2", "Local terminal"),
            element("p", "Install the officially documented tools using your approved process. No script installs workstation tools automatically. Run from this checkout."));
        } else if (mode === "codespaces") {
          content.append(element("h2", "Codespaces (optional)"),
            externalLink("Open Codespaces setup", "https://codespaces.new/olivMertens/workshop-mcp", "secondary"),
            element("p", "Codespaces opens GitHub's creation flow. Review quota, costs and the published branch before creating a machine. Local unpushed changes are not included."));
        }
        if (mode && state.environment.tools) content.append(
          commandBlock("Check tools / PowerShell", "& .\\scripts\\check-tools.ps1"),
          disclosure("Using bash", commandBlock("Check tools / bash", "bash ./scripts/check-tools.sh")));
        content.append(element("p", "Start with module 00. It checks your tools and explains how to prepare your test environment."),
          link("Explore module 00", "#/module/00", "primary"));
        content.append(disclosure("Installation and preparation details",
          notice("Stable random names, not extra quota.",
            "Prepare one private participant file before Terraform. Reuse its suffix and state through cleanup. A new resource group does not reset subscription or regional quotas."),
          markdown(state.documents.gettingStarted.content, state.documents.gettingStarted.sourcePath),
          link("Your Azure context", "#/deployment", "secondary")));
      }
      function deploymentContext() {
        const section = element("section", undefined, "launch-panel");
        section.append(element("h2", "Your deployment, not a shared demo tenant."),
          element("p", "Choose and verify your approved non-production tenant and subscription in your own terminal. Keep IDs out of the board. These context helpers do not deploy or validate a workshop module."),
          link("Read the context and permission guide", "#/deployment", "secondary"));
        if (state.environment.context.powershell) section.append(commandBlock("Select Azure context / PowerShell",
          `& .\\${state.environment.context.powershell.replaceAll("/", "\\")}${language === "fr" ? " -Language fr" : ""}`));
        if (state.environment.context.bash) section.append(commandBlock("Select Azure context / bash",
          `source ./${state.environment.context.bash} ${language}`));
        section.append(element("p", "Read the script first. Run it in the same terminal used for the real module. No credentials or IDs are collected here.", "field-message"));
        return section;
      }
      function architecture(module) {
        const figure = element("figure", undefined, "architecture");
        figure.append(element("h2", "Architecture and security flow"),
          element("span", "Planned target - not deployed or validated", "pill"));
        const scroll = element("div", undefined, "diagram-scroll");
        scroll.tabIndex = 0;
        scroll.setAttribute("role", "region");
        scroll.setAttribute("aria-label", `${t("Architecture and security flow")}: ${module.title}`);
        const image = element("img");
        image.src = module.diagram.svg;
        image.alt = `${module.module} / ${module.title}. ${t("Planned target - not deployed or validated")}. ` +
          (module.learning.match(/\*\*(?:Diagram|Schéma)\s?:\*\* ([\s\S]+?)(?=\n\n)/)?.[1].replaceAll("\n", " ") || "");
        image.addEventListener("error", () => {
          image.hidden = true;
          scroll.append(notice("Warning", "Diagram unavailable. Check the published assets and refresh; no deployment is implied.", "warning"));
        }, { once: true });
        scroll.append(image);
        const caption = element("figcaption", "Scroll the diagram or open its full-size SVG.");
        const actions = element("div", undefined, "action-row");
        actions.append(externalLink("Open SVG", module.diagram.svg, "secondary"),
          externalLink("Open PNG", module.diagram.png, "secondary"),
          externalLink("Editable draw.io source", module.diagram.editable, "secondary"));
        figure.append(scroll, caption, actions,
          disclosure("More detail: Mermaid source",
            element("p", "GitHub renders this Mermaid source. Here, the matching SVG preserves the verified icons and routing. Both come from the same draw.io source."),
            commandBlock("Mermaid diagram", module.diagramSource.content, "Copy diagram")));
        return figure;
      }
      function nextStep(module) {
        const section = element("section", undefined, "next-step");
        section.append(element("h2", "Next step"));
        if (module.module === "99") {
          section.append(element("p", "Cleanup first, then repeat only with a new approved environment and prefix."),
            link("Workshop overview", "#/overview", "primary"));
        } else {
          section.append(element("p", "This is navigation, not a claim that the current stage passed. Run the published validator before continuing."));
          const index = state.modules.indexOf(module);
          const next = state.modules.find((item) => item.module === "99" && module.module === "06") || state.modules[index + 1];
          const anchor = moduleLink(next, "primary");
          anchor.prepend(document.createTextNode(`${next.module} / `));
          section.append(anchor);
          if (module.module === "06") section.append(element("p", "Core path: clean up"),
            link("Optional: explore other clients first", "#/module/07", "secondary"));
        }
        return section;
      }
    function showPractice() {
      content.append(element("h1", "Make the call. Understand the boundary."),
        element("p", "Connect your own deployed MCP server in a real client. Discover a tool, make a controlled call, then compare what happened with what should happen.", "lead"),
        notice("No credentials in this page.",
          "Only the endpoint goes here, in page memory. The canvas does not call your server, save connection details or run code. Commands and prompts must be reviewed and run by you."));
      content.append(link("Choose your workspace", "#/start", "secondary"));
      const launch = disclosure("Workspace and launch options");
      launch.append(element("h2", "Start your workspace"));
      const actions = element("div", undefined, "action-row");
      actions.append(externalLink("Open Codespaces setup", "https://codespaces.new/olivMertens/workshop-mcp", "primary"),
