        dot.title = t(labels[module.status]);
        anchor.append(dot);
        nav.append(anchor);
      }
    }
    async function refresh() {
      if (loading) return;
      loading = true;
      const button = document.getElementById("refresh");
      button.disabled = true;
      message.className = "";
      message.textContent = t("Loading workshop content...");
      try {
        const response = staticSite ? await fetch("journey.json") :
          await fetch("/journey", { headers: { "x-board-key": key } });
        const result = await response.json();
        if (!response.ok) throw new Error(result.error || `Content request failed (${response.status}).`);
