$files['infra/workload/main.tf'] = @'
terraform {
  required_version = ">= 1.16.6, < 2.0.0"
  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "= 5.9.0"
    }
  }
}

provider "azurerm" {
  use_cli                         = true
  resource_provider_registrations = "none"
  features {
    resource_group {
      prevent_deletion_if_contains_resources = true
    }
  }
}

locals {
  stem           = "mcp-${var.participant_prefix}-${var.resource_suffix}"
  compact_prefix = substr(var.participant_prefix, 0, 6)
  legacy_suffix  = length(var.resource_suffix) == 10
  names = {
    resource_group = coalesce(var.existing_resource_group_name, "rg-${local.stem}")
    storage        = local.legacy_suffix ? "stmcp${var.participant_prefix}${var.resource_suffix}" : "st${local.compact_prefix}${var.resource_suffix}"
    function_app   = local.legacy_suffix ? "func-${local.stem}" : "func-mcp-${local.compact_prefix}-${var.resource_suffix}"
    api_management = "apim-${local.stem}"
    portal_plan    = "plan-${local.stem}-portal"
    portal_app     = "web-${local.stem}-portal"
  }
  tags = {
    workshop = local.stem
    owner    = var.owner
    expiry   = var.expiry
  }
}

resource "azurerm_resource_group" "workshop" {
  count    = var.existing_resource_group_name == null ? 1 : 0
  name     = local.names.resource_group
  location = var.location
  tags     = local.tags
}

data "azurerm_resource_group" "existing" {
  count = var.existing_resource_group_name == null ? 0 : 1
  name  = var.existing_resource_group_name
}

output "resource_group_name" {
  value = var.existing_resource_group_name == null ? azurerm_resource_group.workshop[0].name : data.azurerm_resource_group.existing[0].name
}

output "resource_names" {
  description = "Planned MCP service names only. No MCP endpoint is created. The separate public portal is optional."
  value       = local.names
}

output "resource_tags" {
  value = local.tags
}
'@

$files['infra/workload/portal.tf'] = @'
locals {
  workload_group    = var.existing_resource_group_name == null ? azurerm_resource_group.workshop[0].name : data.azurerm_resource_group.existing[0].name
  workload_location = var.existing_resource_group_name == null ? azurerm_resource_group.workshop[0].location : var.location
}

resource "azurerm_service_plan" "portal" {
  count               = var.public_portal_enabled ? 1 : 0
  name                = local.names.portal_plan
  resource_group_name = local.workload_group
  location            = local.workload_location
  os_type             = "Linux"
  sku_name            = "B1"
  tags                = local.tags
}

resource "azurerm_linux_web_app" "portal" {
  count                                          = var.public_portal_enabled ? 1 : 0
  name                                           = local.names.portal_app
  resource_group_name                            = local.workload_group
  location                                       = local.workload_location
  service_plan_id                                = azurerm_service_plan.portal[0].id
  https_only                                     = true
  public_network_access_enabled                  = true
  ftp_publish_basic_authentication_enabled       = false
  webdeploy_publish_basic_authentication_enabled = false
  client_affinity_enabled                        = false
  tags                                           = local.tags

  site_config {
    always_on                         = true
    minimum_tls_version               = "1.2"
    scm_minimum_tls_version           = "1.2"
    ftps_state                        = "Disabled"
    http2_enabled                     = true
    app_command_line                  = "node server.mjs"
    health_check_path                 = "/health"
    health_check_eviction_time_in_min = 2
    application_stack {
      node_version = "22-lts"
    }
  }

  app_settings = {
    SCM_DO_BUILD_DURING_DEPLOYMENT = "false"
    WEBSITE_RUN_FROM_PACKAGE       = "1"
  }
}

output "public_portal_url" {
  description = "Public documentation only, not an authenticated MCP endpoint. Null until explicitly opted in."
  value       = var.public_portal_enabled ? "https://${azurerm_linux_web_app.portal[0].default_hostname}" : null
}
'@

$files['infra/workload/README.md'] = @'
# Workload foundation

By default this root manages one dedicated workshop resource group, or reads an approved existing group.
An explicit persistent opt-in adds a public Linux App Service B1 portal; see [hosting](../../docs/HOSTING.md).
It does not deploy an MCP server. Planned MCP service names are outputs for later modules, not created resources.
Terraform requires 1.16.6+ below 2; AzureRM is locked to 5.9.0.

Start with [workspace preparation](../../docs/GETTING-STARTED.md), or [the French guide](../../docs/fr/GETTING-STARTED.md).
Both workstation routes use this root and the same private `.workshop/participant.tfvars.json`.
Keep one private state per participant. Do not share state or generate new names on every module.
Fresh preparations use a saved 64-bit cryptographic suffix, even when participant labels are identical.
Storage and Function names shorten only the human prefix to six characters, keeping all random bits
within the Storage 24-character and Functions host-ID 32-character limits.
Legacy 10-character suffixes keep every original name. See the start guide's naming table.
Restore missing private parameters rather than generating replacements for an existing deployment.

New-group mode requires approved group-creation authority at subscription scope.
Existing-group mode uses only a data source and does not manage the group or its tags.
Future child-resource creation and role assignments need their own scoped permissions.
No automatic resource-provider registration is enabled.

Only after context, plan and cost approval:

```powershell
terraform -chdir=infra/workload init -lockfile=readonly
if ($LASTEXITCODE -ne 0) { throw 'Terraform init failed.' }
terraform '-chdir=infra\workload' plan '-var-file=..\..\.workshop\participant.tfvars.json' '-out=..\..\.workshop\workload.tfplan'
if ($LASTEXITCODE -ne 0) { throw 'Terraform plan failed.' }
```

The equivalent bash commands use `&&` between init and plan.
Review the saved plan privately. Apply it only with separate explicit approval.
When full teardown of this root is intended, prepare a destroy plan with the same var-file and state:

```powershell
terraform '-chdir=infra\workload' plan -destroy '-var-file=..\..\.workshop\participant.tfvars.json' '-out=..\..\.workshop\destroy.tfplan'
if ($LASTEXITCODE -ne 0) { throw 'Terraform destroy plan failed.' }
```

After explicit deletion approval, applying that reviewed saved plan removes only managed objects.
The provider refuses to delete a nonempty managed group. Never disable this protection to bypass cleanup.
Existing groups are data sources, not destroy targets. Preserve their unrelated contents and identities.
An expiry tag does not schedule deletion. Full module 99 cleanup is still pending.

Offline checks after provider initialization:

```powershell
terraform -chdir=infra/workload fmt -check -recursive
terraform -chdir=infra/workload validate
terraform -chdir=infra/workload test
```

The tests use a mock Azure provider and plan-only runs. They create no Azure resources.
Eleven runs cover new/existing groups, legacy compatibility, 64-bit names at minimum/maximum prefix lengths,
shared-group isolation, invalid names, default-off hosting and the opt-in TLS/runtime settings.
Module 00's [offline validator](../../modules/00-prerequisites/README.md#validate) also covers local HTTP,
bundle integrity, private-file exclusion, and synthetic preflight/deployment failures.

## Sources

- [Azure naming rules](https://learn.microsoft.com/azure/azure-resource-manager/management/resource-name-rules).
- [AzureRM group](https://registry.terraform.io/providers/hashicorp/azurerm/5.9.0/docs/resources/resource_group).
- [Linux web app](https://registry.terraform.io/providers/hashicorp/azurerm/5.9.0/docs/resources/linux_web_app).
- [App Service secretless deployment](https://learn.microsoft.com/azure/app-service/deploy-authentication-types).
- [Terraform mocks](https://developer.hashicorp.com/terraform/language/tests/mocking).

Last verified: 2026-10-14. Mock tests do not establish Azure deployment compatibility.
'@

$files['infra/workload/tests/foundation.tftest.hcl'] = @'
mock_provider "azurerm" {}

variables {
  participant_prefix = "p01"
  resource_suffix    = "0123456789"
  location           = "westeurope"
  owner              = "alice"
  expiry             = "2099-12-31"
}

run "dedicated_group" {
  command = plan
  assert {
    condition     = length(azurerm_resource_group.workshop) == 1 && length(data.azurerm_resource_group.existing) == 0
    error_message = "Default mode must manage exactly one dedicated resource group."
  }
  assert {
    condition     = output.resource_group_name == "rg-mcp-p01-0123456789" && output.resource_names.storage == "stmcpp010123456789"
    error_message = "Names must use the saved participant prefix and suffix."
  }
  assert {
    condition = (output.resource_names.function_app == "func-mcp-p01-0123456789" &&
      output.resource_names.api_management == "apim-mcp-p01-0123456789" &&
      output.resource_names.portal_plan == "plan-mcp-p01-0123456789-portal" &&
    output.resource_names.portal_app == "web-mcp-p01-0123456789-portal")
    error_message = "Every legacy service name must remain byte-for-byte unchanged."
  }
  assert {
    condition     = output.resource_tags.owner == "alice" && output.resource_tags.expiry == "2099-12-31"
    error_message = "Required ownership tags are missing."
  }
  assert {
    condition     = length(azurerm_service_plan.portal) == 0 && length(azurerm_linux_web_app.portal) == 0 && output.public_portal_url == null
    error_message = "Default mode must create no billable portal or pretend that a URL exists."
  }
}

run "existing_group" {
  command = plan
  variables {
    existing_resource_group_name = "rg-synthetic-admin-provided"
  }
  assert {
    condition     = length(azurerm_resource_group.workshop) == 0 && length(data.azurerm_resource_group.existing) == 1
    error_message = "Existing group mode must read, never manage, the administrator's group."
  }
  assert {
    condition     = output.resource_names.resource_group == "rg-synthetic-admin-provided"
    error_message = "Name outputs must preserve the administrator-provided group."
  }
}

run "different_participant" {
  command = plan
  variables {
    resource_suffix = "abcdef0123"
  }
  assert {
    condition     = output.resource_names.storage != run.dedicated_group.resource_names.storage && output.resource_group_name != run.dedicated_group.resource_group_name
    error_message = "Different participant suffixes must produce different group and global service names."
  }
}

run "invalid_suffix" {
  command = plan
  variables {
    resource_suffix = "same"
  }
  expect_failures = [var.resource_suffix]
}

run "public_portal_opt_in" {
  command = plan
  variables {
    public_portal_enabled = true
  }
  assert {
    condition     = length(azurerm_service_plan.portal) == 1 && azurerm_service_plan.portal[0].sku_name == "B1" && azurerm_service_plan.portal[0].os_type == "Linux"
    error_message = "An opt-in must provision exactly one B1 Linux plan."
  }
  assert {
    condition     = azurerm_linux_web_app.portal[0].https_only && !azurerm_linux_web_app.portal[0].ftp_publish_basic_authentication_enabled && !azurerm_linux_web_app.portal[0].webdeploy_publish_basic_authentication_enabled
    error_message = "Portal TLS and secretless publishing protections must remain enabled."
  }
  assert {
    condition     = azurerm_linux_web_app.portal[0].site_config[0].ftps_state == "Disabled" && azurerm_linux_web_app.portal[0].site_config[0].application_stack[0].node_version == "22-lts" && azurerm_linux_web_app.portal[0].site_config[0].app_command_line == "node server.mjs"
    error_message = "Use the selected supported runtime and read-only server; do not add FTP or implicit build/start behavior."
  }
}

run "new_suffix_maximum_prefix" {
  command = plan
  variables {
    participant_prefix    = "abcdefgh"
    resource_suffix       = "0123456789abcdef"
    public_portal_enabled = true
  }
  assert {
    condition     = output.resource_names.storage == "stabcdef0123456789abcdef" && length(output.resource_names.storage) == 24 && can(regex("^[a-z0-9]{3,24}$", output.resource_names.storage))
    error_message = "Keep all 64 random bits and fit the global Storage name into 24 lowercase alphanumeric characters."
  }
  assert {
    condition     = output.resource_names.function_app == "func-mcp-abcdef-0123456789abcdef" && length(output.resource_names.function_app) == 32
    error_message = "Keep all random bits within the first 32 Function host-ID characters."
  }
  assert {
    condition     = output.resource_group_name == "rg-mcp-abcdefgh-0123456789abcdef" && length(output.resource_group_name) <= 90 && length(output.resource_names.api_management) <= 50
    error_message = "Group and API Management names must preserve the participant identity and fit Azure limits."
  }
  assert {
    condition = alltrue([
      for name in [output.resource_names.function_app, output.resource_names.api_management, output.resource_names.portal_plan, output.resource_names.portal_app] :
      length(name) <= 60 && can(regex("^[a-z][a-z0-9-]*[a-z0-9]$", name))
    ])
    error_message = "Service names must use valid DNS-compatible characters without trailing hyphens."
  }
  assert {
    condition     = azurerm_linux_web_app.portal[0].name == output.resource_names.portal_app && azurerm_service_plan.portal[0].name == output.resource_names.portal_plan
    error_message = "Actual portal resources must use the central names, not separate naming formulas."
  }
}

run "new_suffix_minimum_prefix" {
  command = plan
  variables {
    participant_prefix = "ab"
    resource_suffix    = "fedcba9876543210"
  }
  assert {
    condition     = output.resource_names.storage == "stabfedcba9876543210" && length(output.resource_names.storage) == 20 && length(output.resource_names.function_app) == 28
    error_message = "The shortest allowed participant prefix must still retain all random bits and valid service lengths."
  }
}

run "shared_group_first_participant" {
  command = plan
  variables {
    participant_prefix           = "abcdefgh"
    resource_suffix              = "0123456789abcdef"
    existing_resource_group_name = "rg-synthetic-shared"
    public_portal_enabled        = true
  }
  assert {
    condition     = length(azurerm_resource_group.workshop) == 0 && output.resource_names.resource_group == "rg-synthetic-shared"
    error_message = "A shared administrator-owned group must not be managed."
  }
}

run "shared_group_second_participant" {
  command = plan
  variables {
    participant_prefix           = "abcdefgh"
    resource_suffix              = "fedcba9876543210"
    existing_resource_group_name = "rg-synthetic-shared"
    public_portal_enabled        = true
  }
  assert {
    condition = alltrue([
      for key in ["storage", "function_app", "api_management", "portal_app", "portal_plan"] :
      output.resource_names[key] != run.shared_group_first_participant.resource_names[key]
    ])
    error_message = "Identical participant labels in one shared group must still have different names for every service."
  }
  assert {
    condition     = output.resource_names.resource_group == run.shared_group_first_participant.resource_names.resource_group && length(azurerm_resource_group.workshop) == 0
    error_message = "Different participant resources must neither rename nor manage the shared group."
  }
}

run "invalid_prefix_length" {
  command = plan
  variables {
    participant_prefix = "abcdefghi"
    resource_suffix    = "0123456789abcdef"
  }
  expect_failures = [var.participant_prefix]
}

run "invalid_intermediate_suffix" {
  command = plan
  variables {
    resource_suffix = "0123456789abcd"
  }
  expect_failures = [var.resource_suffix]
}
'@

$files['infra/workload/variables.tf'] = @'
variable "participant_prefix" {
  type        = string
  description = "Participant label, not an email or real user identifier."
  validation {
    condition     = can(regex("^[a-z][a-z0-9]{1,7}$", var.participant_prefix))
    error_message = "Use 2-8 lowercase letters/digits, starting with a letter."
  }
}

variable "resource_suffix" {
  type        = string
  description = "Stable 64-bit random suffix from the private preparation script. Existing 40-bit suffixes remain unchanged. Never regenerate during an active deployment."
  validation {
    condition     = can(regex("^([a-f0-9]{10}|[a-f0-9]{16})$", var.resource_suffix))
    error_message = "Use the saved 16-character lowercase hex suffix, or preserve an existing 10-character legacy suffix."
  }
}

variable "location" {
  type        = string
  description = "Explicit region approved after subscription quota, availability and policy checks."
  validation {
    condition     = can(regex("^[a-z][a-z0-9]+$", var.location))
    error_message = "Use the Azure location code, such as westeurope, not a display name."
  }
}

variable "owner" {
  type        = string
  description = "Non-sensitive participant label for ownership."
  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,31}$", var.owner))
    error_message = "Use a 2-32 character lowercase label, not an email or personal data."
  }
}

variable "expiry" {
  type        = string
  description = "Cleanup date tag, not an automatic deletion schedule."
  validation {
    condition     = can(formatdate("YYYY-MM-DD", "${var.expiry}T00:00:00Z"))
    error_message = "Use a valid yyyy-MM-dd date."
  }
}

variable "existing_resource_group_name" {
  type        = string
  default     = null
  nullable    = true
  description = "Optional approved existing group. Read-only: never imported, tagged, renamed or destroyed here."
  validation {
    condition = var.existing_resource_group_name == null ? true : (
      can(regex("^[a-zA-Z0-9_().-]{1,90}$", var.existing_resource_group_name)) &&
      !endswith(var.existing_resource_group_name, ".")
    )
    error_message = "Use a 1-90 character resource group name without a trailing period."
  }
}

variable "public_portal_enabled" {
  type        = bool
  default     = false
  nullable    = false
  description = "Explicit opt-in to a paid B1 Linux App Service for public documentation only. Not an MCP server or tenant deployment control plane."
}
'@

