            ForEach-Object { @{ namespace=$_; registrationState=$(if ($global:scenario -eq 'missing-provider' -and $_ -eq 'Microsoft.Web') { 'NotRegistered' } else { 'Registered' }) } }; break }
        'appservice list-locations' { @(@{name='West Europe'}); break }
        'functionapp list-flexconsumption-locations' { @(@{name=$(if ($global:scenario -eq 'wrong-region') { 'eastus' } else { 'westeurope' })}); break }
        'functionapp list-flexconsumption-runtimes' { @(@{name='dotnet-isolated';version=$(if ($global:scenario -eq 'wrong-runtime') { '8.0' } else { '10.0' })}); break }
        'rest --method' {
            if ($args[2] -ne 'get') { throw 'Write attempt refused by synthetic CLI.' }
            if ($args[4] -eq "https://management.azure.com/subscriptions/$global:subscription/locations?api-version=2022-12-01") {
                if ($global:scenario -eq 'invalid-locations') { @{value='not-an-array'} }
                else { @{value=@(@{name='westeurope'})} }
                break
            }
            $global:pageCount++
            $permission = @{actions=@('*');notActions=@()}
            if ($global:scenario -eq 'permission-denied') { $permission.notActions=@('Microsoft.Resources/subscriptions/resourceGroups/write') }
            $response = @{value=@($permission)}
            if ($global:scenario -eq 'pagination' -and $global:pageCount -eq 1) {
                $response.value=@(@{actions=@('*/read');notActions=@()})
                $response.nextLink="https://management.azure.com/subscriptions/$global:subscription/providers/Microsoft.Authorization/permissions?api-version=2022-04-01&skiptoken=synthetic"
            }
            if ($global:scenario -eq 'unsafe-pagination') { $response.nextLink='https://example.invalid/never-call' }
            $response
            break
        }
        default { throw "Unexpected Azure command; synthetic CLI allows only read/check commands." }
    }
    if ($global:scenario -eq 'cli-error' -and $args[0] -eq 'provider') { $global:LASTEXITCODE=1; 'synthetic private error must not be printed'; return }
    if ($global:scenario -eq 'invalid-json' -and $args[0] -eq 'provider') { 'not-json'; return }
    ConvertTo-Json -InputObject $result -Depth 20 -Compress
}
$directory = '${directory.replaceAll("'", "''")}'
$path = Join-Path $directory 'parameters.json'
$reviewPath = Join-Path $directory 'capacity.json'
foreach ($global:scenario in @('valid', 'pagination', 'wrong-context', 'override', 'permission-denied', 'group-quota',
    'missing-provider', 'cli-error', 'invalid-json', 'unsafe-pagination', 'portal-valid', 'mcp-valid', 'wrong-runtime',
    'wrong-region', 'missing-review', 'stale-review', 'future-review', 'wrong-review-target', 'insufficient-review', 'unsafe-parameters', 'invalid-locations', 'invalid-groups')) {
    $global:pageCount=0
    $global:calls.Clear()
    $stage = if ($global:scenario -in @('portal-valid','missing-provider','missing-review','stale-review','future-review','wrong-review-target','insufficient-review')) { 'portal' }
        elseif ($global:scenario -in @('mcp-valid','wrong-runtime','wrong-region')) { 'mcp' } else { 'foundation' }
    $parameters = @{participant_prefix='p01';resource_suffix='0123456789';location='westeurope';owner='alice';
        expiry=[datetime]::UtcNow.AddDays(1).ToString('yyyy-MM-dd');existing_resource_group_name=$(if ($stage -ne 'foundation') { 'rg-synthetic-admin' } else { $null })}
    if ($global:scenario -eq 'unsafe-parameters') { $parameters.resource_suffix='../../outside' }
    $parameters | ConvertTo-Json | Set-Content -LiteralPath $path
    $before = Get-Content -LiteralPath $path -Raw
    $checked = [datetime]::UtcNow.AddMinutes(-1)
    if ($global:scenario -eq 'stale-review') { $checked=$checked.AddDays(-2) }
    if ($global:scenario -eq 'future-review') { $checked=$checked.AddDays(1) }
    @{subscriptionId=$(if ($global:scenario -eq 'wrong-review-target') { [guid]::NewGuid().ToString() } else { $global:subscription.ToString() });
        location='westeurope';stage=$stage;unit=$(if ($stage -eq 'portal') { 'workers' } else { 'MB' });
        availableUnits=$(if ($global:scenario -eq 'insufficient-review') { 0 } else { 512000 });
        checkedAtUtc=$checked.ToString('yyyy-MM-ddTHH:mm:ssZ');costApproved=$true } | ConvertTo-Json | Set-Content -LiteralPath $reviewPath
    $arguments = @{TenantId=$global:tenant;SubscriptionId=$global:subscription;ParametersPath=$path;Stage=$stage}
    if ($stage -ne 'foundation' -and $global:scenario -ne 'missing-review') { $arguments.CapacityReviewPath=$reviewPath }
    if ($global:scenario -eq 'override') { $env:ARM_CLIENT_ID='synthetic-override' }
    $failed=$false
    try { $output = & '${script}' @arguments | Out-String }
    catch { $failed=$true; $output=$_.Exception.Message + ' ' + $_.ScriptStackTrace }
    finally { Remove-Item Env:ARM_CLIENT_ID -ErrorAction SilentlyContinue }
    $expected = $global:scenario -in @('valid','pagination','portal-valid','mcp-valid')
    if ($failed -eq $expected) { throw "Unexpected result for $global:scenario : $output" }
    if ($output -match 'synthetic private error must not be printed') { throw 'Private CLI error leaked.' }
    if ((Get-Content -LiteralPath $path -Raw) -cne $before) { throw 'Preflight changed participant parameters.' }
    if ($env:AZURE_EXTENSION_USE_DYNAMIC_INSTALL) { throw 'Extension policy was not restored.' }
    if ($global:calls | Where-Object { $_ -match '(^| )(login|set|register|create|delete|update|deploy|apply)( |$)' }) { throw 'Preflight attempted a state-changing command.' }
    if ($global:scenario -eq 'pagination' -and $global:pageCount -ne 2) { throw 'Permission pagination was not followed.' }
    if ($global:scenario -eq 'unsafe-pagination' -and $global:pageCount -ne 1) { throw 'Unsafe pagination was followed.' }
    Write-Output "PASS synthetic $global:scenario (expected HTTP N/A; no Azure access)"
}
`], { encoding: "utf8", timeout: 60000 });
    assert.equal(result.status, 0, result.stderr + result.stdout);
    assert.equal((result.stdout.match(/PASS synthetic /g) ?? []).length, 22);
});
'@

$files['scripts/prepare-workshop.ps1'] = @'
#requires -Version 7.4
[CmdletBinding()]
param(
    [Parameter(Mandatory)][ValidatePattern('^[a-z][a-z0-9]{1,7}$')][string]$ParticipantPrefix,
    [Parameter(Mandatory)][ValidatePattern('^[a-z][a-z0-9]+$')][string]$Location,
    [Parameter(Mandatory)][ValidatePattern('^[a-z][a-z0-9-]{1,31}$')][string]$Owner,
    [Parameter(Mandatory)][string]$Expiry,
    [ValidatePattern('^[a-zA-Z0-9_().-]{1,90}$')][string]$ExistingResourceGroupName,
    [switch]$EnablePublicPortal
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$date = [datetime]::MinValue
if (-not [datetime]::TryParseExact($Expiry, 'yyyy-MM-dd', [Globalization.CultureInfo]::InvariantCulture,
        [Globalization.DateTimeStyles]::None, [ref]$date) -or $date.Date -le [datetime]::UtcNow.Date) {
    throw 'Expiry must be a future UTC date in yyyy-MM-dd format. It is a tag, not automatic deletion.'
}
if ($ExistingResourceGroupName -and $ExistingResourceGroupName.EndsWith('.')) {
    throw 'A resource group name must not end with a period.'
}
$directory = Join-Path (Split-Path $PSScriptRoot -Parent) '.workshop'
$path = Join-Path $directory 'participant.tfvars.json'
$configuration = [ordered]@{
    participant_prefix = $ParticipantPrefix
    location = $Location
    owner = $Owner
    expiry = $Expiry
    existing_resource_group_name = $(if ($ExistingResourceGroupName) { $ExistingResourceGroupName } else { $null })
}
if (Test-Path -LiteralPath $directory) {
    $entry = Get-Item -LiteralPath $directory -Force
    if (-not $entry.PSIsContainer -or $entry.Attributes -band [IO.FileAttributes]::ReparsePoint) {
        throw '.workshop must be a regular local directory.'
    }
} else { [void](New-Item -ItemType Directory -Path $directory) }
if (Test-Path -LiteralPath $path) {
    $entry = Get-Item -LiteralPath $path -Force
    if ($entry.PSIsContainer -or $entry.Attributes -band [IO.FileAttributes]::ReparsePoint) {
        throw 'Participant parameters must be a regular local file.'
    }
    $before = Get-Content -LiteralPath $path -Raw
    $existing = $before | ConvertFrom-Json -AsHashtable
    $keys = @($configuration.Keys) + 'resource_suffix', 'public_portal_enabled'
    $expectedCount = $configuration.Count + 1 + $(if ($existing.ContainsKey('public_portal_enabled')) { 1 } else { 0 })
    if ($existing.Count -ne $expectedCount -or ($existing.Keys | Where-Object { $_ -notin $keys }) -or
        $existing.resource_suffix -isnot [string] -or $existing.resource_suffix -cnotmatch '^([a-f0-9]{10}|[a-f0-9]{16})$' -or
        ($existing.ContainsKey('public_portal_enabled') -and $existing.public_portal_enabled -isnot [bool])) {
        throw 'Invalid participant file. Restore the original private parameters; do not regenerate names for deployed resources.'
    }
    foreach ($key in $configuration.Keys) {
        if ($existing[$key] -cne $configuration[$key]) {
            throw "Participant setting '$key' differs. Refusing to overwrite parameters or silently replace resources."
        }
    }
    if ($EnablePublicPortal -and (-not $existing.ContainsKey('public_portal_enabled') -or -not $existing.public_portal_enabled)) {
        $existing.public_portal_enabled = $true
        $temporary = Join-Path $directory "participant-$([guid]::NewGuid().ToString('N')).tmp"
        [IO.File]::WriteAllText($temporary, ($existing | ConvertTo-Json) + "`n", [Text.UTF8Encoding]::new($false))
        try {
            if ([IO.File]::ReadAllText($path) -cne $before) { throw 'Participant parameters changed concurrently; no replacement was made.' }
            [IO.File]::Move($temporary, $path, $true)
        } finally { if ([IO.File]::Exists($temporary)) { [IO.File]::Delete($temporary) } }
        Write-Output 'PASS public portal explicitly opted in; existing names and state preserved. Review the paid-resource plan before applying.'
    } else { Write-Output 'PASS existing participant parameters reused unchanged.' }
} else {
    $workload = Join-Path (Split-Path $PSScriptRoot -Parent) 'infra' 'workload'
    $statePaths = @(
        (Join-Path $workload 'terraform.tfstate'),
        (Join-Path $workload 'terraform.tfstate.backup'),
        (Join-Path $workload 'terraform.tfstate.d'),
        (Join-Path $workload '.terraform' 'terraform.tfstate')
    )
    $savedPlans = @(Get-ChildItem -LiteralPath $directory -File -Force |
        Where-Object { $_.Name -match '\.(tfplan|tfstate)(\.backup)?$' })
    if (($statePaths | Where-Object { Test-Path -LiteralPath $_ }) -or $savedPlans.Count -gt 0) {
        throw 'Participant parameters are missing but local state or saved plans exist. Restore the original private parameters; refusing to generate replacement names.'
    }
    if ($EnablePublicPortal) { $configuration.public_portal_enabled = $true }
    $configuration.resource_suffix = [Convert]::ToHexString([Security.Cryptography.RandomNumberGenerator]::GetBytes(8)).ToLowerInvariant()
    $bytes = [Text.UTF8Encoding]::new($false).GetBytes(($configuration | ConvertTo-Json) + "`n")
    $stream = [IO.File]::Open($path, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
    try { $stream.Write($bytes) } finally { $stream.Dispose() }
    Write-Output 'PASS private participant parameters created with a stable random suffix.'
}
Write-Output 'PASS no Azure command executed. Keep .workshop and Terraform state private and backed up through cleanup.'
Write-Output 'NEXT read docs/GETTING-STARTED.md before any Terraform plan or apply.'
'@

$files['scripts/prepare-workshop.sh'] = @'
#!/usr/bin/env bash
set -euo pipefail
command -v pwsh >/dev/null || { printf '%s\n' 'FAIL PowerShell 7.4+ is required. See docs/GETTING-STARTED.md.' >&2; exit 1; }
exec pwsh -NoProfile -File "$(dirname "${BASH_SOURCE[0]}")/prepare-workshop.ps1" "$@"
'@

$files['scripts/render-architecture.py'] = @'
"""Render the deliberately small, validated mxGraph subset used by this workshop."""

import argparse
import copy
import hashlib
import re
import shutil
import struct
import textwrap
import urllib.parse
import xml.etree.ElementTree as ET
import zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SVG = "http://www.w3.org/2000/svg"
ET.register_namespace("", SVG)
SUPPORTED = {
    "shape", "rounded", "fillColor", "strokeColor", "strokeWidth", "dashed",
    "fontColor", "fontSize", "fontStyle", "align", "verticalAlign", "whiteSpace",
    "spacingLeft", "image", "aspect", "container", "html", "edgeStyle",
    "endArrow", "endFill", "exitX", "exitY", "entryX", "entryY",
}


def svg_node(parent, name, attributes=None, text=None):
    node = ET.SubElement(parent, f"{{{SVG}}}{name}", {k: str(v) for k, v in (attributes or {}).items()})
    node.text = text
    return node


def style(cell):
    pairs = [part.split("=", 1) for part in cell.get("style", "").split(";") if part]
    if any(len(pair) != 2 for pair in pairs):
        raise ValueError(f"Unsupported named mxGraph style: {cell.get('id')}")
    result = dict(pairs)
    if set(result) - SUPPORTED:
        raise ValueError(f"Unsupported styles on {cell.get('id')}: {set(result) - SUPPORTED}")
    if result.get("rounded", "0") != "0" or result.get("html", "0") != "0":
        raise ValueError("Only square-cornered components and plain text are supported.")
    for key, allowed in {
        "shape": {"rectangle", "text", "image"}, "align": {"left"}, "verticalAlign": {"middle"},
        "whiteSpace": {"wrap"}, "edgeStyle": {"orthogonalEdgeStyle"}, "aspect": {"fixed"},
        "fontStyle": {"0", "1"}, "container": {"0", "1"}, "dashed": {"0", "1"},
    }.items():
        if key in result and result[key] not in allowed:
            raise ValueError(f"Unsupported {key} value on {cell.get('id')}: {result[key]}")
    return result


def number(element, name, default=0):
    return float(element.get(name, default))


def bounds(cell, cells):
    geometry = cell.find("mxGeometry")
    if geometry is None or geometry.get("relative", "0") != "0":
        raise ValueError(f"Vertex needs absolute geometry: {cell.get('id')}")
    x, y = number(geometry, "x"), number(geometry, "y")
    parent = cells.get(cell.get("parent"))
    if parent is not None and parent.get("vertex") == "1":
        px, py, _, _ = bounds(parent, cells)
        x, y = x + px, y + py
    return x, y, number(geometry, "width"), number(geometry, "height")


def segments(points):
    return list(zip(points, points[1:]))


def intersects_box(segment, box):
    (x1, y1), (x2, y2) = segment
    x, y, width, height = box
    if y1 == y2:
        return y < y1 < y + height and max(min(x1, x2), x) < min(max(x1, x2), x + width)
    return x < x1 < x + width and max(min(y1, y2), y) < min(max(y1, y2), y + height)


def edge_points(cell, cells, styles):
    source, target = cells[cell.get("source")], cells[cell.get("target")]
    sx, sy, sw, sh = bounds(source, cells)
    tx, ty, tw, th = bounds(target, cells)
    s = styles[cell.get("id")]
    for key in ("exitX", "exitY", "entryX", "entryY"):
        if key not in s:
            raise ValueError(f"Explicit anchors required: {cell.get('id')}")
    start = (sx + sw * float(s["exitX"]), sy + sh * float(s["exitY"]))
    end = (tx + tw * float(s["entryX"]), ty + th * float(s["entryY"]))
    waypoints = cell.findall("./mxGeometry/Array[@as='points']/mxPoint")
    points = [start] + [(number(p, "x"), number(p, "y")) for p in waypoints] + [end]
    if any(a == b or (a[0] != b[0] and a[1] != b[1]) for a, b in segments(points)):
        raise ValueError(f"Source routing must contain nonzero orthogonal segments: {cell.get('id')}")
    before, final = points[-2:]
    if abs(final[0] - before[0]) + abs(final[1] - before[1]) < 15:
        raise ValueError("Final arrow approach is too short.")
    if not ((float(s["entryX"]) in (0, 1) and before[1] == final[1]) or
            (float(s["entryY"]) in (0, 1) and before[0] == final[0])):
        raise ValueError("Arrow must approach a target border perpendicularly.")
    return points


def check_geometry(vertices, edges, cells, styles):
    for edge, points in edges:
        excluded = {edge.get("source"), edge.get("target")}
        for vertex in vertices:
            if vertex.get("id") in excluded or styles[vertex.get("id")].get("container") == "1":
                continue
            if vertex.get("parent") in excluded:
                continue
            if any(intersects_box(segment, bounds(vertex, cells)) for segment in segments(points)):
                raise ValueError(f"Edge {edge.get('id')} crosses {vertex.get('id')}")
    all_segments = [(edge.get("id"), segment) for edge, points in edges for segment in segments(points)]
    for index, (first_id, (a, b)) in enumerate(all_segments):
        for second_id, (c, d) in all_segments[index + 1:]:
            if first_id == second_id:
                continue
            horizontal = a[1] == b[1]
            if horizontal == (c[1] == d[1]):
                axis, lane = (0, 1) if horizontal else (1, 0)
                if max(min(a[axis], b[axis]), min(c[axis], d[axis])) < min(max(a[axis], b[axis]), max(c[axis], d[axis])):
                    if abs(a[lane] - c[lane]) < 16:
                        raise ValueError(f"Parallel edge overlap/clearance: {first_id}, {second_id}")
            else:
                h1, h2, v1, v2 = (a, b, c, d) if horizontal else (c, d, a, b)
                if min(h1[0], h2[0]) <= v1[0] <= max(h1[0], h2[0]) and min(v1[1], v2[1]) <= h1[1] <= max(v1[1], v2[1]):
                    raise ValueError(f"Perpendicular edge intersection: {first_id}, {second_id}")


def embed_icon(parent, source, prefix, box):
    if not source.startswith("data:image/svg+xml,"):
        raise ValueError("Icons must be embedded SVG, not remote or filesystem URLs.")
    icon = ET.fromstring(urllib.parse.unquote(source.split(",", 1)[1]))
    if icon.tag != f"{{{SVG}}}svg" or "viewBox" not in icon.attrib:
        raise ValueError("Icon must have an SVG root and viewBox.")
    for node in icon.iter():
        if node.tag.rsplit("}", 1)[-1] in ("script", "foreignObject", "style"):
            raise ValueError("Active or stylesheet content is forbidden in icons.")
        for attribute, value in node.attrib.items():
            if attribute.lower().startswith("on"):
                raise ValueError("Event handlers are forbidden.")
            if attribute.rsplit("}", 1)[-1] == "href" and not value.startswith("#"):
                raise ValueError("External icon references are forbidden.")
            if "url(" in value and not re.fullmatch(r"url\(#[A-Za-z0-9_.:-]+\)", value):
                raise ValueError("External CSS assets are forbidden.")
    identifiers = {node.get("id"): prefix + node.get("id") for node in icon.iter() if node.get("id")}
    for node in icon.iter():
        for attribute, value in list(node.attrib.items()):
            if attribute == "id":
                node.set(attribute, identifiers[value])
            else:
                for old, new in identifiers.items():
                    value = value.replace(f"url(#{old})", f"url(#{new})")
                    if value == f"#{old}":
                        value = f"#{new}"
                node.set(attribute, value)
    x, y, width, height = box
    icon.attrib.update(x=str(x), y=str(y), width=str(width), height=str(height), preserveAspectRatio="xMidYMid meet")
    parent.append(copy.deepcopy(icon))


def add_text(parent, value, box, s):
    x, y, width, height = box
    size = float(s.get("fontSize", 16))
    left = float(s.get("spacingLeft", 16))
    line_width = max(1, int((width - left - 14) / (size * 0.58)))
    lines = [line for paragraph in value.split("\n") for line in (textwrap.wrap(paragraph, line_width, break_long_words=False) or [""])]
    line_height = size * 1.35
    if len(lines) * line_height > height - 8:
        raise ValueError(f"Text does not fit its source box: {value}")
    baseline = y + (height - len(lines) * line_height) / 2 + size
    text = svg_node(parent, "text", {"x": x + left, "y": baseline, "font-size": size,
        "font-family": "Segoe UI, Arial, sans-serif", "fill": s.get("fontColor", "#172c48"),
        "font-weight": "600" if s.get("fontStyle") == "1" else "400"})
    for index, line in enumerate(lines):
        svg_node(text, "tspan", {"x": x + left, "dy": 0 if index == 0 else line_height}, line)


def render(page, output, check=False):
    graph = page.find("mxGraphModel")
    if graph is None:
        raise ValueError("Use uncompressed drawio XML.")
    width, height = int(graph.get("pageWidth")), int(graph.get("pageHeight"))
    cells = {cell.get("id"): cell for cell in graph.findall("./root/mxCell")}
    styles = {identifier: style(cell) for identifier, cell in cells.items()}
    vertices = [cell for cell in cells.values() if cell.get("vertex") == "1"]
    edges = [(cell, edge_points(cell, cells, styles)) for cell in cells.values() if cell.get("edge") == "1"]
    check_geometry(vertices, edges, cells, styles)
    root = ET.Element(f"{{{SVG}}}svg", {"viewBox": f"0 0 {width} {height}", "width": str(width),
        "height": str(height), "role": "img", "aria-labelledby": "diagram-title diagram-description"})
    svg_node(root, "title", {"id": "diagram-title"}, page.get("name"))
    svg_node(root, "desc", {"id": "diagram-description"}, page.get("description"))
    svg_node(root, "rect", {"width": width, "height": height, "fill": "#ffffff"})
    defs = svg_node(root, "defs")
    for color, suffix in (("#1659dc", "blue"), ("#14704b", "green")):
        marker = svg_node(defs, "marker", {"id": f"arrow-{suffix}", "viewBox": "0 0 10 10",
            "refX": 10, "refY": 5, "markerWidth": 8, "markerHeight": 8, "orient": "auto"})
        svg_node(marker, "path", {"d": "M 0 0 L 10 5 L 0 10 Z", "fill": color})
    groups = {}

    def render_vertex(vertex):
        identifier = vertex.get("id")
        if identifier in groups:
            return groups[identifier]
        s = styles[identifier]
        x, y, w, h = bounds(vertex, cells)
        parent = cells.get(vertex.get("parent"))
        if parent is not None and parent.get("vertex") == "1":
            owner = render_vertex(parent)
            px, py, _, _ = bounds(parent, cells)
            x, y = x - px, y - py
        else:
            owner = root
        group = svg_node(owner, "g", {"id": identifier, "transform": f"translate({x:g} {y:g})"})
        groups[identifier] = group
        if s.get("shape") == "image":
            embed_icon(group, s.get("image", ""), identifier + "-", (0, 0, w, h))
        else:
            if s.get("shape", "rectangle") != "text":
                attributes = {"width": w, "height": h, "rx": 0, "fill": s.get("fillColor", "#eaf0ff"),
                    "stroke": s.get("strokeColor", "#1659dc"), "stroke-width": s.get("strokeWidth", 1)}
                if s.get("dashed") == "1":
                    attributes["stroke-dasharray"] = "8 6"
                svg_node(group, "rect", attributes)
            if vertex.get("value"):
                add_text(group, vertex.get("value"), (0, 0, w, h), s)
        return group

    for vertex in vertices:
        render_vertex(vertex)
    for edge, points in edges:
        s = styles[edge.get("id")]
        if s.get("endArrow") != "block" or s.get("endFill") != "1":
            raise ValueError("Only filled block arrowheads are supported.")
        color = s.get("strokeColor", "#1659dc")
        if color not in ("#1659dc", "#14704b"):
            raise ValueError("Unsupported edge color.")
        path = svg_node(root, "path", {"d": "M " + " L ".join(f"{x:g} {y:g}" for x, y in points),
            "fill": "none", "stroke": color, "stroke-width": 2,
            "marker-end": f"url(#arrow-{'green' if color == '#14704b' else 'blue'})"})
        if s.get("dashed") == "1":
            path.set("stroke-dasharray", "6 5")
        if edge.get("value"):
            if len(points) != 2 or points[0][1] != points[1][1]:
                raise ValueError("Place routed-edge labels in explicit source text cells.")
            x, y = points[0]
            label_box = (x + 28, y - 58, points[1][0] - x - 56, 50)
            add_text(root, edge.get("value"), label_box, {"fontSize": "12", "spacingLeft": "0"})
    data = ET.tostring(root, encoding="utf-8", xml_declaration=True) + b"\n"
    if check:
        if output.read_bytes() != data:
            raise ValueError(f"Stale SVG export: {output.name}")
    else:
        output.write_bytes(data)
    return width, height


def check_png(path, svg, size):
    data = path.read_bytes()
    if data[:8] != b"\x89PNG\r\n\x1a\n" or struct.unpack(">II", data[16:24]) != size:
        raise ValueError(f"Invalid PNG dimensions/signature: {path.name}")
    position, provenance = 8, None
    while position < len(data):
        length = struct.unpack(">I", data[position:position + 4])[0]
        chunk = data[position + 4:position + 8 + length]
        crc = struct.unpack(">I", data[position + 8 + length:position + 12 + length])[0]
        if zlib.crc32(chunk) != crc:
            raise ValueError(f"Invalid PNG chunk: {path.name}")
        if chunk.startswith(b"tEXtworkshop-svg-sha256\0"):
            provenance = chunk.split(b"\0", 1)[1].decode("ascii")
        position += length + 12
    if position != len(data) or provenance != hashlib.sha256(svg.read_bytes()).hexdigest():
        raise ValueError(f"Stale PNG export: {path.name}. Regenerate SVG and PNG together.")


def stamp_png(path, svg):
    data = path.read_bytes()
    if data[:8] != b"\x89PNG\r\n\x1a\n":
        raise ValueError(f"PNG rendering failed: {path.name}")
    payload = b"tEXtworkshop-svg-sha256\0" + hashlib.sha256(svg.read_bytes()).hexdigest().encode("ascii")
    chunk = struct.pack(">I", len(payload) - 4) + payload + struct.pack(">I", zlib.crc32(payload))
    path.write_bytes(data[:33] + chunk + data[33:])


def mermaid_label(value):
    return (value.replace("#", "#35;").replace("&", "#38;").replace('"', "#quot;")
            .replace("<", "#60;").replace(">", "#62;").replace("\n", " / "))


def mermaid(page):
    cells = {cell.get("id"): cell for cell in page.findall("./mxGraphModel/root/mxCell")}
    styles = {identifier: style(cell) for identifier, cell in cells.items()}
    components = [cell for cell in cells.values() if cell.get("vertex") == "1"
                  and styles[cell.get("id")].get("shape", "rectangle") == "rectangle"
                  and styles[cell.get("id")].get("container") != "1"]
    boundaries = [cell for cell in cells.values() if styles[cell.get("id")].get("container") == "1"]
    identifiers = {cell.get("id"): "n_" + re.sub(r"[^a-zA-Z0-9_]", "_", cell.get("id")) for cell in components}
    if len(set(identifiers.values())) != len(components):
        raise ValueError("Mermaid component identifiers collide.")
    groups = {boundary.get("id"): [] for boundary in boundaries}
    outside = []
    for cell in components:
        x, y, w, h = bounds(cell, cells)
        owners = []
        for boundary in boundaries:
            bx, by, bw, bh = bounds(boundary, cells)
            if bx <= x and by <= y and x + w <= bx + bw and y + h <= by + bh:
                owners.append(boundary.get("id"))
        if len(owners) > 1:
            raise ValueError("Nested/overlapping Mermaid ownership needs an explicit reviewed representation.")
        (groups[owners[0]] if owners else outside).append(cell)

    lines = ["flowchart LR"]
    for cell in cells.values():
        if cell.get("id", "").startswith("lane-label-"):
            lines.append("  %% " + cell.get("value").replace("\n", " / "))

    def declare(cell, indent):
        if not cell.get("value"):
            raise ValueError("Every Mermaid component needs a label.")
        lines.append(f'{indent}{identifiers[cell.get("id")]}["{mermaid_label(cell.get("value"))}"]')

    for cell in outside:
        declare(cell, "  ")
    for index, boundary in enumerate(boundaries):
        caption = cells["boundary-label-" + boundary.get("id").removeprefix("boundary-")].get("value")
        lines.append(f'  subgraph boundary_{index}["{mermaid_label(caption)}"]')
        for cell in groups[boundary.get("id")]:
            declare(cell, "    ")
        lines.append("  end")
        color = styles[boundary.get("id")]["strokeColor"]
        lines.append(f"  style boundary_{index} fill:#ffffff,stroke:{color},stroke-dasharray:8 6")
    for cell in cells.values():
        if cell.get("edge") != "1":
            continue
        source, target = cell.get("source"), cell.get("target")
        if source not in identifiers or target not in identifiers:
            raise ValueError("Mermaid must preserve every edge between real components.")
        arrow = "-.->" if styles[cell.get("id")].get("dashed") == "1" else "-->"
        label = f'|"{mermaid_label(cell.get("value"))}"|' if cell.get("value") else ""
        lines.append(f"  {identifiers[source]} {arrow}{label} {identifiers[target]}")
    for cell in components:
        s = styles[cell.get("id")]
        lines.append(f'  style {identifiers[cell.get("id")]} fill:{s["fillColor"]},stroke:{s["strokeColor"]},color:{s["fontColor"]}')
    return "\n".join(lines)


def architecture_documents(pages, directory, check):
    for language in ("en", "fr"):
        french = language == "fr"
        name = "STEPS.fr.md" if french else "STEPS.md"
        lines = [
            "# " + ("L'architecture, étape par étape" if french else "Architecture, step by step"), "",
            ("Ces schémas montrent les objectifs du parcours, pas des déploiements réalisés. "
             "Consultez le suivi de construction pour les preuves de validation." if french else
             "These diagrams show learning targets, not deployed resources. See build progress for validation evidence."), "",
            ("Le protocole de contexte de modèle (MCP) relie un client à des outils. "
             "Chaque étape ajoute un contrôle ou explique une responsabilité." if french else
             "The Model Context Protocol (MCP) connects a client to tools. "
             "Each step adds a control or explains an ownership boundary."), "",
            ("[Ce qui est réellement disponible](../../docs/fr/IMPLEMENTATION-STATUS.md). "
             "[Modifier les schémas et vérifier les icônes](README.fr.md)." if french else
             "[What is actually available](../../docs/IMPLEMENTATION-STATUS.md). "
             "[Edit diagrams and verify icon provenance](README.md)."), "",
            ("Fichier généré depuis `workshop.drawio` : ne le modifiez pas séparément. "
             "Les cadres représentent des périmètres ; les vues répétées désignent le même environnement. "
             "GitHub affiche Mermaid ; l'application affiche le SVG équivalent avec ses icônes et son routage vérifiés."
             if french else
             "Generated from `workshop.drawio`; do not edit separately. Frames are ownership boundaries; "
             "repeated views refer to the same environment. GitHub renders Mermaid; "
             "the application displays the equivalent SVG with verified icons and routing."), "",
        ]
        for page in pages:
            if not page.get("id").endswith("." + language):
                continue
            identifier = page.get("id")
            lines.extend([
                "## " + page.get("name"), "", page.get("description"), "",
                f"[SVG]({identifier}.svg) · [PNG]({identifier}.png)", "",
                "```mermaid", mermaid(page), "```", "",
            ])
        lines.extend([
            "## Sources", "",
            "- [Draw.io](workshop.drawio).",
            "- [GitHub Mermaid](https://docs.github.com/en/get-started/writing-on-github/working-with-advanced-formatting/creating-diagrams).",
            "- [Mermaid flowcharts](https://mermaid.js.org/syntax/flowchart.html).", "",
            ("Dernière vérification : 2026-10-14." if french else "Last verified: 2026-10-14."), "",
        ])
        data = "\n".join(lines)
        output = directory / name
        if check:
            if output.read_text(encoding="utf-8") != data:
                raise ValueError(f"Stale Mermaid documentation: {name}")
        else:
            output.write_text(data, encoding="utf-8", newline="\n")
        print(f"PASS {name}: nine Mermaid graphs from the same Draw.io source")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--svg-only", action="store_true", help="Regenerate SVG only; PNG exports then need regeneration before publication.")
    mode.add_argument("--check", action="store_true", help="Verify source, SVG freshness and PNG provenance without changing exports or starting a browser.")
    parser.add_argument("--browser", help="Existing Chromium/Edge executable for local, offline PNG rendering.")
    args = parser.parse_args()
    browser = args.browser or shutil.which("msedge") or shutil.which("chromium") or shutil.which("google-chrome")
    if not args.svg_only and not args.check and (not browser or not Path(browser).is_file()):
        parser.error("PNG export requires an existing Chromium/Edge --browser path; no tool is installed automatically.")
    automation = browser_process = None
    source = ROOT / "assets" / "architecture" / "workshop.drawio"
    document = ET.parse(source)
    pages = document.findall("diagram")
    expected = {f"{module}.{language}" for module in ("00", "01", "02", "03", "04", "05", "06", "07", "99") for language in ("en", "fr")}
    if {page.get("id") for page in pages} != expected or len(pages) != len(expected):
        raise ValueError("Exactly one English and French page per module is required.")
    try:
        if not args.svg_only and not args.check:
            from playwright.sync_api import sync_playwright

            automation = sync_playwright().start()
            browser_process = automation.chromium.launch(executable_path=str(browser), headless=True)
        for page in pages:
            output = source.with_name(page.get("id") + ".svg")
            width, height = render(page, output, args.check)
            if args.check:
                check_png(output.with_suffix(".png"), output, (width, height))
            elif not args.svg_only:
                png = output.with_suffix(".png")
                png.unlink(missing_ok=True)
                tab = browser_process.new_page(viewport={"width": width, "height": height}, device_scale_factor=1)
                try:
                    tab.route("http://**/*", lambda route: route.abort())
                    tab.route("https://**/*", lambda route: route.abort())
                    tab.goto(output.as_uri())
                    tab.screenshot(path=str(png))
                finally:
                    tab.close()
                stamp_png(png, output)
                check_png(png, output, (width, height))
            print(f"PASS {page.get('id')}: XML, routing, text fit, embedded SVG" + (", PNG" if not args.svg_only else ""))
        architecture_documents(pages, source.parent, args.check)
    finally:
        if browser_process:
            browser_process.close()
        if automation:
            automation.stop()


if __name__ == "__main__":
    main()
'@

$files['scripts/select-azure-context.ps1'] = @'
param([ValidateSet('en', 'fr')][string]$Language = 'en')

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$fr = $Language -eq 'fr'
Get-Command az -ErrorAction Stop | Out-Null

. (Join-Path $PSScriptRoot 'context-common.ps1')
Assert-WorkshopInteractiveEnvironment

$cloud = az cloud show --query name --output tsv
if ($LASTEXITCODE -ne 0 -or $cloud -ne 'AzureCloud') {
    throw 'This workshop targets Azure public cloud. Cloud selection failed or does not match; nothing will be deployed.'
}
$tenant = Read-Host $(if ($fr) { 'ID du tenant Entra de test approuvé (terminal uniquement)' } else { 'Approved non-production Entra tenant ID (terminal only)' })
$subscription = Read-Host $(if ($fr) { 'ID de votre abonnement Azure de test approuvé' } else { 'Your approved non-production Azure subscription ID' })
$parsedTenant = [guid]::Empty
$parsedSubscription = [guid]::Empty
if (-not [guid]::TryParseExact($tenant, 'D', [ref]$parsedTenant) -or $parsedTenant -eq [guid]::Empty -or
    -not [guid]::TryParseExact($subscription, 'D', [ref]$parsedSubscription) -or $parsedSubscription -eq [guid]::Empty) {
    throw 'Enter valid tenant and subscription IDs from your approved environment. Do not paste them into the board.'
}
$confirmation = Read-Host $(if ($fr) { 'Tapez NONPROD pour confirmer le périmètre de test et la connexion interactive' } else { 'Type NONPROD to confirm the approved test scope and interactive sign-in' })
if ($confirmation -cne 'NONPROD') { throw 'Selection cancelled. No sign-in or deployment was started.' }

az login --tenant $tenant --output none
if ($LASTEXITCODE -ne 0) { throw 'Azure sign-in failed. Stop here; do not deploy.' }
az account set --subscription $subscription
if ($LASTEXITCODE -ne 0) { throw 'Subscription selection failed. Stop here; do not deploy.' }
$accountJson = az account show --query '{subscription:id,tenant:tenantId,state:state}' --output json
if ($LASTEXITCODE -ne 0) { throw 'Could not verify Azure context. Stop here; do not deploy.' }
$account = $accountJson | ConvertFrom-Json
if ($account.tenant -ne $tenant -or $account.subscription -ne $subscription -or $account.state -ne 'Enabled') {
    throw 'The active tenant/subscription does not match the approved target, or the subscription is not enabled. Stop here.'
}

$env:ARM_TENANT_ID = $tenant
$env:ARM_SUBSCRIPTION_ID = $subscription
Write-Output $(if ($fr) {
    'PASS contexte : tenant et abonnement vérifiés. Variables ARM définies dans ce processus uniquement. Aucune ressource créée ; ce contrôle ne valide pas le module 00.'
} else {
    'PASS context: tenant and subscription verified. ARM variables set in this process only. No resources created; this check does not validate module 00.'
})
'@

$files['scripts/select-azure-context.sh'] = @'
#!/usr/bin/env bash

if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then
  printf '%s\n' 'Run in your current bash terminal: source ./scripts/select-azure-context.sh [en|fr]' >&2
  exit 1
fi

_workshop_select_azure_context() {
  local language="${1:-en}" name cloud tenant subscription confirmation actual
  [[ "$language" == en || "$language" == fr ]] || { printf '%s\n' 'Language must be en or fr.' >&2; return 1; }
  command -v az >/dev/null || { printf '%s\n' 'Azure CLI is required.' >&2; return 1; }
  for name in ARM_CLIENT_ID ARM_CLIENT_SECRET ARM_CLIENT_CERTIFICATE_PATH ARM_CLIENT_CERTIFICATE \
    ARM_CLIENT_CERTIFICATE_PASSWORD ARM_USE_MSI ARM_USE_OIDC ARM_OIDC_TOKEN ARM_ACCESS_KEY \
    AZURE_CLIENT_ID AZURE_CLIENT_SECRET AZURE_CLIENT_CERTIFICATE_PATH ARM_ENVIRONMENT \
    ARM_USE_CLI ARM_USE_AKS_WORKLOAD_IDENTITY ARM_OIDC_TOKEN_FILE_PATH ARM_OIDC_REQUEST_TOKEN \
    ARM_OIDC_REQUEST_URL AZURE_FEDERATED_TOKEN_FILE AZURE_AUTHORITY_HOST ARM_MSI_ENDPOINT \
    ARM_CLIENT_ID_FILE_PATH ARM_TENANT_ID_FILE_PATH ARM_SUBSCRIPTION_ID_FILE_PATH; do
    if [[ -n "${!name:-}" ]]; then
      printf '%s\n' 'An authentication override is present. Use a separate approved interactive-user terminal; do not combine credential flows.' >&2
      return 1
    fi
  done
  cloud="$(az cloud show --query name --output tsv)" || return 1
  [[ "$cloud" == AzureCloud ]] || { printf '%s\n' 'This workshop targets Azure public cloud. Stop here.' >&2; return 1; }
  if [[ "$language" == fr ]]; then
    read -r -p 'ID du tenant Entra de test approuvé (terminal uniquement) : ' tenant || return 1
    read -r -p 'ID de votre abonnement Azure de test approuvé : ' subscription || return 1
    read -r -p 'Tapez NONPROD pour confirmer le périmètre de test et la connexion interactive : ' confirmation || return 1
  else
    read -r -p 'Approved non-production Entra tenant ID (terminal only): ' tenant || return 1
    read -r -p 'Your approved non-production Azure subscription ID: ' subscription || return 1
    read -r -p 'Type NONPROD to confirm the approved test scope and interactive sign-in: ' confirmation || return 1
  fi
  local id_pattern='^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
  if [[ ! "$tenant" =~ $id_pattern || ! "$subscription" =~ $id_pattern ||
    -z "${tenant//[0-]/}" || -z "${subscription//[0-]/}" ]]; then
    printf '%s\n' 'Enter valid approved tenant/subscription IDs; never paste them into the board.' >&2
    return 1
  fi
  [[ "$confirmation" == NONPROD ]] || { printf '%s\n' 'Selection cancelled. No sign-in or deployment was started.' >&2; return 1; }
  az login --tenant "$tenant" --output none || { printf '%s\n' 'Azure sign-in failed. Stop here.' >&2; return 1; }
  az account set --subscription "$subscription" || { printf '%s\n' 'Subscription selection failed. Stop here.' >&2; return 1; }
  actual="$(az account show --query "join('|', [id, tenantId, state])" --output tsv)" ||
    { printf '%s\n' 'Could not verify Azure context. Stop here.' >&2; return 1; }
  if [[ "${actual,,}" != "${subscription,,}|${tenant,,}|enabled" ]]; then
    printf '%s\n' 'The active tenant/subscription does not match the approved target, or the subscription is not enabled. Stop here.' >&2
    return 1
  fi
  export ARM_TENANT_ID="$tenant" ARM_SUBSCRIPTION_ID="$subscription"
  if [[ "$language" == fr ]]; then
    printf '%s\n' 'PASS contexte : tenant et abonnement vérifiés. Variables ARM dans ce processus uniquement. Aucune ressource créée ; le module 00 reste à valider.'
  else
    printf '%s\n' 'PASS context: tenant and subscription verified. ARM variables set in this process only. No resources created; module 00 still needs validation.'
  fi
}

_workshop_select_azure_context "$@"
'@

$files['scripts/site.test.mjs'] = @'
import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, readFileSync, readdirSync, rmSync, existsSync, mkdirSync, writeFileSync, symlinkSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { buildSite } from "./build-site.mjs";

const root = fileURLToPath(new URL("../", import.meta.url));

test("Git preserves SVG bytes and binary PNG provenance on Windows checkouts", () => {
    const attributes = readFileSync(join(root, ".gitattributes"), "utf8");
    assert.match(attributes, /^\*\.svg text eol=lf$/m);
    assert.match(attributes, /^\*\.png binary$/m);
});

test("public site exports only the allowlist, with no capability, root URLs, private files or API dependency", (t) => {
    const temporary = mkdtempSync(join(tmpdir(), "workshop-site-"));
    t.after(() => rmSync(temporary, { recursive: true, force: true }));
    const output = join(temporary, "public");
    const result = buildSite(root, output);
    assert.equal(result.files, 50);
    assert.deepEqual(readdirSync(output).sort(), [".nojekyll", "assets", "index.html", "journey.json", "locale-fr.js"]);
    const html = readFileSync(join(output, "index.html"), "utf8");
    assert.match(html, /const staticSite = "true" === "true"/);
    assert.match(html, /const key = ""/);
    assert.doesNotMatch(html, /__BOARD_KEY__|__STATIC_SITE__|src="\/|image\.src = `\/assets/);
    assert.match(html, /Content-Security-Policy/);
    const journey = JSON.parse(readFileSync(join(output, "journey.json"), "utf8"));
    assert.equal(journey.revision, undefined);
    for (const language of [journey, journey.translations.fr]) {
        assert.equal(language.modules.length, 9);
        assert.match(language.documents.presenter.sourcePath, /PRESENTER\.md$/);
        assert.match(language.documents.presenter.content, /\?lang=fr#\/start/);
        assert.match(language.documents.presenter.content, /\?lang=en#\/start/);
        assert.match(language.documents.gettingStarted.content, /PRESENTER\.md/);
        for (const module of language.modules) {
            assert.match(module.diagramSource.content, /^flowchart LR\n/);
            assert.ok(language.documents.architecture.content.replaceAll("\r\n", "\n").includes(module.diagramSource.content));
            for (const path of Object.values(module.diagram)) {
                assert.match(path, /^assets\/architecture\//);
                assert.ok(existsSync(join(output, path)));
            }
            assert.match(language.documents.implementation.sourcePath, /IMPLEMENTATION-STATUS\.md$/);
        }
    }
    assert.deepEqual(readdirSync(join(output, "assets")).sort(), ["architecture", "icons"]);
    assert.throws(() => buildSite(root, output), { code: "EEXIST" });
});

test("static export refuses linked source directories before reading their contents or creating output", (t) => {
    const temporary = mkdtempSync(join(tmpdir(), "workshop-site-link-"));
    t.after(() => rmSync(temporary, { recursive: true, force: true }));
    const fixture = join(temporary, "repository");
    const outside = join(temporary, "outside");
    mkdirSync(fixture);
    mkdirSync(outside);
    writeFileSync(join(outside, "PROGRESS.md"), "Synthetic content that must not be read.");
    symlinkSync(outside, join(fixture, "docs"), process.platform === "win32" ? "junction" : "dir");
    const output = join(temporary, "public");
    assert.throws(() => buildSite(fixture, output), /regular files inside the repository/);
    assert.equal(existsSync(output), false);
});
